'use strict';

const DispatcherBase = require('./dispatcher-base');
const { kCount, kDispatch, kLabel } = require('./symbols');

class Agent extends DispatcherBase {
  constructor({ label = 'agent', prefix = '>' } = {}) {
    super({ label });
    this.prefix = prefix;
  }

  [kDispatch](path, handler) {
    handler(this.prefix + ' ' + this[kLabel] + ' ' + path + ' #' + this[kCount]);
    return true;
  }
}

module.exports = Agent;
